<template><section class="grid"><div class="card"><h1>금융상품 추천</h1><button class="secondary" @click="seed">샘플 상품 저장</button><button @click="recommend">최근 AI 분석으로 추천 생성</button><p class="error" v-if="error">{{error}}</p></div><div class="card"><h2>추천 결과</h2><div class="card" v-for="r in recommendations" :key="r.id"><h3>{{r.product.bank_name}} - {{r.product.product_name}}</h3><p>최고 {{r.product.max_rate}}%</p><p>{{r.reason}}</p></div></div><div class="card"><h2>상품 목록</h2><p v-for="p in products" :key="p.id">{{p.bank_name}} - {{p.product_name}} · {{p.max_rate}}%</p></div></section></template>
<script setup>import { onMounted, ref } from 'vue'; import api from '@/api/axios'; const products=ref([]); const recommendations=ref([]); const error=ref(''); const load=async()=>{products.value=(await api.get('/api/v1/finance/products/')).data; recommendations.value=(await api.get('/api/v1/finance/recommendations/')).data}; const seed=async()=>{await api.post('/api/v1/finance/products/seed/'); await load()}; const recommend=async()=>{const ai=(await api.get('/api/v1/analysis/ai/')).data; if(!ai.length){error.value='먼저 AI 분석을 생성해주세요.'; return} await api.post('/api/v1/finance/recommendations/create/',{ai_analysis_id:ai[0].id}); await load()}; onMounted(load)</script>
